create table if not exists public.ils_professional_assignment_mutation_commit_stress_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_commit_stress_tests enable row level security; alter table public.ils_professional_assignment_mutation_commit_stress_tests force row level security; revoke all on public.ils_professional_assignment_mutation_commit_stress_tests from anon,authenticated; insert into public.ils_professional_assignment_mutation_commit_stress_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('AUTH_REQUIRED','BLOCK','BLOCK',true,'Commit path must fail closed when auth.uid() is absent.'),('CROSS_USER_REPLAY','BLOCK','BLOCK',true,'Mutation gate requires the assignment professional to equal auth.uid().'),('CROSS_STREAM_REPLAY','BLOCK','BLOCK',true,'Assignment/work stream is bound to the selected assignment link.'),('INVALID_OPERATION','BLOCK','BLOCK',true,'Only supported mutation operations are accepted.'),('OPERATION_STATUS_MISMATCH','BLOCK','BLOCK',true,'Target status must exactly match the requested operation.'),('STALE_STATUS','BLOCK','BLOCK',true,'Row-lock plus current-status validation prevents stale writes.'),('INVALID_LIFECYCLE','BLOCK','BLOCK',true,'Transition validator rejects invalid state jumps.'),('STALE_ELIGIBILITY','BLOCK','BLOCK',true,'ACTIVATE re-checks current assignment eligibility.'),('REPLAY_AFTER_REVOKE','BLOCK','BLOCK',true,'Revoked state cannot be reactivated.'),('REPLAY_AFTER_COMPLETE','BLOCK','BLOCK',true,'Completed state cannot be reactivated.'),('DUPLICATE_ASSIGNMENT','BLOCK','BLOCK',true,'Unique work_stream/work_item_id constraint prevents duplicate assignment links.'),('VALID_COMMIT','ALLOW','ALLOW',true,'Valid owned assignment with valid transition and eligibility may commit.'),('AUDIT_ATOMICITY','REQUIRED','REQUIRED',true,'Successful mutation must commit its audit/event evidence in the same transaction.'),('LIVE_AUTH_E2E','PENDING','PENDING',true,'No authenticated live assignment exists in TEST; no synthetic live E2E result is claimed.');